<template>
  <div>
    <div id="etokurac" class=""></div>
    <div v-if="reSpeedo" id="speedo" :class="['speedo-gauge-container car-speedo', { speedoFugitive: fugitive }]">
      <span class="value-text">km/h</span>
    </div>
  </div>
</template>

<script>

let Gauge = require("svg-gauge");

export default {
  name: "Speedometer",
  props: ['fugitive'],
  data() {
    return {
      speed: 800,
      maxspeed: 1500,
      speedo: null,
      reSpeedo: true
    }
  },
  watch: {
    speed(value) {
      this.speedo.setValueAnimated((value > 999 ? 999 : value), 0);
    },
    maxspeed() {
      this.reSpeedo = false;
      setTimeout(() => {
        console.log("this is the third message")
        this.reSpeedo = true;
      }, 50);
    },
    reSpeedo(value) {
      if (value === true) {
        setTimeout(() => {
          this.speedo = Gauge(
              document.getElementById("speedo"), {
                max: this.maxspeed,
                dialStartAngle: 90,
                dialEndAngle: 0,
                value: this.speed
              }
          );
        }, 50);
      }
    }
  },
  mounted() {
    let that = this;
    this.$nextTick(function () {
      that.speedo = Gauge(
          document.getElementById("speedo"), {
            max: that.maxspeed,
            dialStartAngle: 90,
            dialEndAngle: 0,
            value: that.speed
          }
      );
    })
  }
}
</script>

<style scoped lang="scss">
div {
  margin-bottom: -20px;
  margin-right: -15px;
}
</style>

<style lang="scss">
.speedoFugitive.car-speedo .value-text {
  color: $orange !important;
}

.speedoFugitive.car-speedo > .gauge .value-text {
  fill: $orange !important;
}

.speedoFugitive > .gauge .value {
  stroke: $orange !important;
}

/* ------ Default Style ---------- */
.speedo-gauge-container {
  width: 170px;
  height: 170px;
}

.speedo-gauge-container > .label {
  position: absolute;
  right: 0;
  top: 0;
  display: inline-block;
  background: rgba(0, 0, 0, 0.5);
  font-family: monospace;
  font-size: 0.8em;
  padding: 5px 10px;
}

.speedo-gauge-container > .gauge .dial {
  stroke: #334455;
  stroke-width: 2;
  fill: rgba(0, 0, 0, 0);
}

.speedo-gauge-container > .gauge .value {
  stroke: rgb(47, 227, 255);
  stroke-width: 2;
  fill: rgba(0, 0, 0, 0);
}

.speedo-gauge-container > .gauge .value-text {
  fill: rgb(47, 227, 255);
  font-family: sans-serif;
  font-weight: bold;
  font-size: 0.8em;
}

/* ----- Alternate Style ----- */
.speedo-gauge-container.car-speedo > .gauge .dial {
  stroke: rgba(lighten($foreground, 20%), 0.5);
  stroke-width: 10;
}

.speedo-gauge-container.car-speedo > .gauge .value {
  transition: stroke 0.4s;
  stroke: $blue;
  stroke-dasharray: none;
  stroke-width: 10;
}


//value
.speedo-gauge-container.car-speedo > .gauge .value-text {
  transition: fill 0.4s;
  font-family: 'Nunito', sans-serif;
  fill: $blue;
  transform: translate3d(26%, 20%, 0);
  display: inline-block;
  font-weight: bolder;
  font-size: 1.7em;
}


//small value
.speedo-gauge-container.car-speedo .value-text {
  transition: color 0.4s;
  font-family: 'Nunito', sans-serif;
  color: $blue;
  position: absolute;
  bottom: -5%;
  right: -1%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  font-size: 1.5em;
}
</style>