<template>
  <div class="wrap">
    <button v-if="debug" style="position: absolute; top: 0px;" v-on:click="show = !show">
      Toggle
    </button>
    <!--<transition name="bounce">
      <ve-progress v-show="actionBar" class="progress"
                   :progress="progress"
                   line="butt"
                   :color="(fugitive ? fugitiveColors.color : policeColors.color)"
                   :emptyColor="(fugitive ? fugitiveColors.emptyColor : policeColors.emptyColor)"
                   thickness="50"
                   emptyThickness="20"
                   :size="100"
                   lineMode="in-over"
                   fontSize="30px"
                   fontColor="#f1f1f1"
      >
        <span slot="legend-caption">{{ legend }}s</span>
      </ve-progress>
    </transition>-->
  </div>
</template>

<script>

export default {
  name: "ActionBar",
  props: ['actionBar'],
  computed: {
    progress() {
      return (this.time > this.maxtime ? 100 : (this.time * 100) / this.maxtime);
    },
    legend() {
      return (this.time > this.maxtime ? 0 : (this.maxtime - this.time).toFixed())
    }
  },
  mounted() {
    if (this.debug) {
      setInterval(() => {
        if (this.show) {
          this.time++;
        }
      }, 1000)
    }
  },
  data() {
    return {
      debug: false,
      time: 0.1,
      maxtime: 10,
      fugitive: false,
      policeColors: {
        color: {
          radial: true,
          colors: [
            {
              color: "#0097ff",
              offset: "50",
              opacity: "0.1",
            },
            {
              color: "#63bfff",
              offset: "100",
              opacity: 0.5,
            },
          ],
        },
        emptyColor: {
          radial: true,
          colors: [
            {
              color: "#0097ff",
              offset: "100",
              opacity: 0.8,
            },
          ],
        },
        emptyColorFill: {
          radial: true,
          colors: [
            {
              color: "#0097ff",
              opacity: 0.3,
            }
          ],
        },
      },
      fugitiveColors: {
        color: {
          radial: true,
          colors: [
            {
              color: "#ffae00",
              offset: "50",
              opacity: "0.1",
            },
            {
              color: "#ffae00",
              offset: "100",
              opacity: 0.5,
            },
          ],
        },
        emptyColor: {
          radial: true,
          colors: [
            {
              color: "#b4851e",
              offset: "100",
              opacity: 0.8,
            },
          ],
        },
        emptyColorFill: {
          radial: true,
          colors: [
            {
              color: "#ffae00",
              opacity: 0.3,
            }
          ],
        },
      }
    }
  },
}
</script>
<style scoped lang="scss">
.bounce-enter-active {
  animation: bounce-in .3s;
}

.bounce-leave-active {
  animation: bounce-in .3s reverse;
}

.wrap {
  width: 100vw;
  height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;

  padding-bottom: 100px;
}

@keyframes bounce-in {
  0% {
    transform: scale(0);
  }
  50% {
    transform: scale(1.2);
  }
  100% {
    transform: scale(1);
  }
}
</style>